describe('Product Page Accessibility - Screen Reader Support', () => {
  beforeEach(() => {
    cy.visit('https://www.saucedemo.com');
  });

  it('should display product images with alt attributes after successful login', () => {
    // Login with standard user
    cy.get('[data-test="user-name"]').type('standard_user');
    cy.get('[data-test="password"]').type('secret_sauce');
    cy.get('[data-test="login-button"]').click();

    // Verify login success
    cy.url().should('include', '/inventory.');

    // Verify product images have alt attributes
    cy.get('[data-testid="inventory-item-img"]').each(($img) => {
      cy.wrap($img).should('have.attr', 'alt');
      cy.wrap($img).should('not.have.attr', 'alt', '');
    });

    // Verify at least one product image exists
    cy.get('[data-testid="inventory-item-img"]').should('have.length.greaterThan', 0);
  });

  it('should display login fields with placeholder attributes', () => {
    // Verify username field has placeholder
    cy.get('[data-testid="user-name"]').should('have.attr', 'placeholder');
    cy.get('[data-testid="user-name"]').should('not.have.attr', 'placeholder', '');

    // Verify password field has placeholder
    cy.get('[data-testid="password"]').should('have.attr', 'placeholder');
    cy.get('[data-testid="password"]').should('not.have.attr', 'placeholder', '');

    // Verify login button is visible
    cy.get('[data-testid="login-button"]').should('be.visible');

    // Verify login button has accessible name
    cy.get('[data-testid="login-button"]').should('have.attr', 'aria-label');
  });
});
